const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const dialogs=$$('dialog');dialogs.forEach(d=>{d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
function openEnquiry(){dialogs.forEach(d=>{if(d.open)d.close()});$('#enquiry').showModal()}
$$('[data-enquire]').forEach(b=>b.addEventListener('click',()=>{if(!document.body.classList.contains('editing'))openEnquiry()}));
$$('#enquiry-form,[data-safari-enquiry]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const fields=[['Name','name'],['Email','email'],['Phone','phone'],['Preferred dates','dates'],['Travellers','travellers'],['Interested in','interest']];const lines=fields.filter(([,key])=>d.get(key)).map(([label,key])=>label+': '+d.get(key));const body='Hello Cotter Safaris,\n\n'+lines.join('\n')+'\n\n'+d.get('message')+'\n';location.href='mailto:info@cottersafaris.co.za?subject='+encodeURIComponent('Safari enquiry — '+d.get('name'))+'&body='+encodeURIComponent(body)}));
$('.menu-toggle').addEventListener('click',()=>{const open=$('header nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open)});$$('header nav a').forEach(a=>a.addEventListener('click',()=>{$('header nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')}));
const sectionObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){$$('header nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))}}),{rootMargin:'-10% 0px -65% 0px'});if(!document.body.dataset.page || document.body.dataset.page==='home')$('main section[id]').forEach(s=>sectionObserver.observe(s));
const photos=[['leopard','Leopard in the wild'],['elephants','Iconic African elephants'],['acacia','Golden African sunset'],['buffalo','African buffalo'],['bird','A glimpse of African birdlife'],['lodge','Luxury safari lodge'],['lion','The spirit of the wild'],['landscape','Untamed waterways'],['giraffes','Grace on the savannah'],['hero','The journey of a lifetime']];let photoIndex=0;function showPhoto(i){photoIndex=(i+photos.length)%photos.length;$('#lightbox-image').src='assets/'+photos[photoIndex][0]+'.webp';$('#lightbox-image').alt=photos[photoIndex][1];$('#photo-caption').textContent=photos[photoIndex][1]+' · '+(photoIndex+1)+' / '+photos.length}$$('[data-gallery]').forEach(b=>b.addEventListener('click',()=>{if(document.body.classList.contains('editing'))return;showPhoto(Number(b.dataset.gallery));$('#lightbox').showModal()}));$('#photo-prev').onclick=()=>showPhoto(photoIndex-1);$('#photo-next').onclick=()=>showPhoto(photoIndex+1);document.addEventListener('keydown',e=>{if($('#lightbox').open){if(e.key==='ArrowLeft')showPhoto(photoIndex-1);if(e.key==='ArrowRight')showPhoto(photoIndex+1)}});
const details={wildlife:['Wildlife Safaris','Get up close to Africa’s iconic wildlife in their natural habitat. Experience unforgettable game viewing and the thrill of the wild. Contact us to discuss your preferred destinations and wildlife experiences.'],luxury:['Luxury & Comfort','Enjoy exceptional accommodation options, from luxury lodges to intimate bush camps, all in incredible locations. Tell us about your interests and preferences to plan your stay.'],philosophy:['Our Safari Philosophy','Our safaris are about more than just seeing wildlife — they’re about experiencing the true spirit of Africa. Breathtaking landscapes, incredible wildlife, warm hospitality and moments that stay with you long after the journey ends.'],landscapes:['Untamed Landscapes','Explore diverse and breathtaking scenery across Africa. From vast savannahs to rugged mountains and serene waterways, let us help you plan your journey.'],authentic:['Authentic Experiences','Connect with local cultures and traditions. Share your interests with us to create your personalised African safari experience.'],journeys:['Memorable Journeys','Create lifelong memories in extraordinary destinations. Every traveller is unique — let us plan a safari to suit your interests, time and budget.']};$$('[data-experience]').forEach(b=>b.addEventListener('click',()=>{if(document.body.classList.contains('editing'))return;const d=details[b.dataset.experience];$('#detail-title').textContent=d[0];$('#detail-copy').textContent=d[1];$('#details').showModal()}));$$('[data-policy]').forEach(b=>b.onclick=()=>{$('#detail-title').textContent=b.dataset.policy==='privacy'?'Privacy Policy':'Terms & Conditions';$('#detail-copy').textContent=b.dataset.policy==='privacy'?'This website uses browser storage only to keep your local text edits. Enquiry details are passed to your email application when you choose to compose an email. Contact Cotter Safaris for its full privacy policy.':'Please contact Cotter Safaris directly for booking terms, availability and cancellation conditions.';$('#details').showModal()});
const editNodes=$$('[data-edit]');const originalText=Object.fromEntries(editNodes.map(n=>[n.dataset.edit,n.innerHTML]));const pageName=document.body.dataset.page||'home';const storageKey='cotter-safaris-text-v2'+(pageName==='home'?'':'-'+pageName);let saved={};try{saved=JSON.parse(localStorage.getItem(storageKey)||'{}');editNodes.forEach(n=>{if(typeof saved[n.dataset.edit]==='string')n.innerHTML=saved[n.dataset.edit]})}catch{}
function editing(on){document.body.classList.toggle('editing',on);$('#edit-toggle').setAttribute('aria-pressed',on);$('#edit-toolbar').hidden=!on;editNodes.forEach(n=>{n.contentEditable=on?'true':'false';n.spellcheck=on})}$('#edit-toggle').onclick=()=>editing(true);$('#done-editing').onclick=()=>editing(false);editNodes.forEach(n=>{n.addEventListener('paste',e=>{if(!document.body.classList.contains('editing'))return;e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'))});n.addEventListener('click',e=>{if(document.body.classList.contains('editing')){e.preventDefault();e.stopPropagation()}})});
function collectEdits(){return Object.fromEntries(editNodes.map(n=>[n.dataset.edit,n.innerHTML]))}$('#save-edits').onclick=()=>{try{localStorage.setItem(storageKey,JSON.stringify(collectEdits()));$('#edit-status').textContent='Saved in this browser.'}catch{$('#edit-status').textContent='Storage unavailable. Use Download HTML to keep your changes.'}};$('#reset-edits').onclick=()=>{editNodes.forEach(n=>n.innerHTML=originalText[n.dataset.edit]);try{localStorage.removeItem(storageKey)}catch{}$('#edit-status').textContent='Original text restored.'};$('#download-page').onclick=()=>{const clone=document.documentElement.cloneNode(true);clone.querySelector('body').classList.remove('editing');clone.querySelector('#edit-toolbar').hidden=true;clone.querySelectorAll('[data-edit]').forEach(n=>n.removeAttribute('contenteditable'));clone.querySelector('#edit-toggle').setAttribute('aria-pressed','false');const url=URL.createObjectURL(new Blob(['<!doctype html>\n'+clone.outerHTML],{type:'text/html'}));const a=document.createElement('a');a.href=url;a.download=pageName==='home'?'index.html':pageName+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#edit-status').textContent='Downloaded. Replace index.html in your website folder to keep these edits.'};

$$('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const category=button.dataset.filter;$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));let count=0;$$('.gallery-photo-card').forEach(card=>{card.hidden=category!=='all'&&card.dataset.category!==category;if(!card.hidden)count++});$('#gallery-count').textContent=count+' photograph'+(count===1?'':'s')}));
